import{_ as n,o as i,c as r,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const o=JSON.parse('{"title":"Artikel schreiben und bearbeiten","description":"","frontmatter":{"title":"Artikel schreiben und bearbeiten"},"headers":[],"relativePath":"hilfe/artikel-schreiben.md","filePath":"hilfe/artikel-schreiben.md"}'),a={name:"hilfe/artikel-schreiben.md"};function l(s,e,h,d,u,c){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="artikel-schreiben-und-bearbeiten" tabindex="-1">Artikel schreiben und bearbeiten <a class="header-anchor" href="#artikel-schreiben-und-bearbeiten" aria-label="Permalink to &quot;Artikel schreiben und bearbeiten&quot;">​</a></h1><p>Schreiben Sie so, dass auch Personen ohne Vorkenntnisse den beschriebenen Arbeitsschritt verstehen. Diese Hinweise gelten für neue Artikel und für die Überarbeitung bestehender Texte. Kopierbare Bausteine finden Sie unter <a href="/hilfe/markdown-und-gestaltung.html">Markdown und Gestaltung</a>.</p><h2 id="eine-klare-aufgabe-beschreiben" tabindex="-1">Eine klare Aufgabe beschreiben <a class="header-anchor" href="#eine-klare-aufgabe-beschreiben" aria-label="Permalink to &quot;Eine klare Aufgabe beschreiben&quot;">​</a></h2><p>Ein Artikel behandelt eine erkennbare Aufgabe oder einen klar abgegrenzten Gegenstand. Sagen Sie zu Beginn, wobei er hilft und welche Voraussetzungen tatsächlich nötig sind. Verwenden Sie genaue Begriffe und übernehmen Sie die sichtbaren Bezeichnungen aus SchILD-NRW 3.</p><p>Erhalten Sie bei Überarbeitungen die fachlichen Einzelheiten, Einschränkungen, Beispiele, Tabellen, Bilder und Bildunterschriften. Sprachliche Vereinfachungen sind möglich; fachliche Änderungen müssen sich begründen lassen. Erfinden Sie keine Voraussetzungen, Programmfunktionen, Parameter oder Ergebnisse. Benennen Sie offene Fragen im Änderungsvorschlag.</p><p>Legen Sie nur Abschnitte mit Inhalt an. Leere Überschriften, Auslassungspunkte oder Füllsätze helfen den Lesenden nicht. Ein kurzer Artikel braucht nicht dieselben Abschnitte wie eine ausführliche Anleitung.</p><h2 id="den-passenden-artikelaufbau-wahlen" tabindex="-1">Den passenden Artikelaufbau wählen <a class="header-anchor" href="#den-passenden-artikelaufbau-wahlen" aria-label="Permalink to &quot;Den passenden Artikelaufbau wählen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Artikeltyp</th><th>Geeigneter Aufbau</th><th>Beispiel</th></tr></thead><tbody><tr><td>Arbeitsanleitung</td><td>Ziel, belegte Voraussetzungen, nummerierte Schritte, erkennbares Ergebnis und bekannte Probleme</td><td>Reports installieren oder Noten eingeben</td></tr><tr><td>Programmreferenz</td><td>Zweck und Aufruf, Felder und Schaltflächen, Wirkungen und Besonderheiten, passende Anleitungen</td><td>Ein Fenster oder einen Karteireiter erklären</td></tr><tr><td>RAP-Funktionsreferenz</td><td>Beschreibung, vorhandene Signatur, belegte Parameter, Rückgabewerte und Beispiele</td><td>Eine RAP-Funktion nachschlagen</td></tr><tr><td>Themenübersicht</td><td>Einstieg in das Thema, sinnvolle Reihenfolge, Sonderfälle und Links zu den Detailartikeln</td><td>Die Arbeitsschritte eines Themenbereichs erschließen</td></tr></tbody></table><h3 id="arbeitsanleitungen" tabindex="-1">Arbeitsanleitungen <a class="header-anchor" href="#arbeitsanleitungen" aria-label="Permalink to &quot;Arbeitsanleitungen&quot;">​</a></h3><ol><li>Erklären Sie das Ziel in ein bis zwei Sätzen.</li><li>Nennen Sie nur belegte Voraussetzungen, etwa ein benötigtes Reportpaket oder Zugriffsrechte auf ein Arbeitsverzeichnis.</li><li>Beschreiben Sie die Handlungsschritte in ihrer tatsächlichen Reihenfolge. Zusammengehörige Auswahl und Bestätigung dürfen in einem Schritt stehen.</li><li>Stellen Sie einen wichtigen Hinweis vor den Schritt, bei dem eine Fehlbedienung Folgen hätte. Erklären Sie eine nötige Rückstellung direkt beim betreffenden Schritt.</li><li>Beschreiben Sie, woran das erfolgreiche Ergebnis zu erkennen ist. Wiederholen Sie dabei nicht bloß den letzten Arbeitsschritt.</li><li>Verknüpfen Sie bekannte Probleme mit konkreten Fundstellen oder Handlungsmöglichkeiten. Vermeiden Sie spekulative Fehlerlisten.</li></ol><p>Ein zusammengehöriger Arbeitsablauf soll sich ohne ständiges Springen zwischen Seiten nachvollziehen lassen. Weiterführende Artikel dürfen gezielt verlinkt werden; umfangreiche Hintergrundinformationen müssen nicht in mehreren Anleitungen wiederholt werden.</p><h3 id="programmreferenzen" tabindex="-1">Programmreferenzen <a class="header-anchor" href="#programmreferenzen" aria-label="Permalink to &quot;Programmreferenzen&quot;">​</a></h3><p>Verwenden Sie die Namen aus der Programmoberfläche. Für mehrere Felder oder Schaltflächen eignet sich eine Tabelle mit „Bezeichnung“, „Bedeutung“ und bei Bedarf „Besonderheit“.</p><p>Nehmen Sie Schulform-, Versions- oder Berechtigungsunterschiede nur auf, wenn sie belegt sind. Verlinken Sie vollständige Arbeitsabläufe, statt sie in jedem Referenzartikel erneut zu erklären.</p><h3 id="rap-funktionsreferenzen" tabindex="-1">RAP-Funktionsreferenzen <a class="header-anchor" href="#rap-funktionsreferenzen" aria-label="Permalink to &quot;RAP-Funktionsreferenzen&quot;">​</a></h3><p>Erhalten Sie Signaturen, Bezeichner und Code wörtlich. Beschreiben Sie Parameter mit Name, Typ und Bedeutung, soweit diese Angaben vorliegen. Bei einer Prozedur darf kein Rückgabewert erfunden werden; dokumentierte <code>var</code>-Ausgaben gehören zu den Parametern. Aus fehlenden Angaben lässt sich nicht ableiten, dass eine Funktion keine Parameter oder keinen Rückgabewert hat.</p><p>Schreiben Sie Pascal-Beispiele in Codeblöcke und die Erläuterungen außerhalb des Codes. Erklären Sie beabsichtigte Codekorrekturen im Änderungsvorschlag. Bezeichnen Sie ein Beispiel nur dann als „getestet“ oder „ausgeführt“, wenn es tatsächlich in der passenden Laufzeit geprüft wurde.</p><h3 id="themenubersichten" tabindex="-1">Themenübersichten <a class="header-anchor" href="#themenubersichten" aria-label="Permalink to &quot;Themenübersichten&quot;">​</a></h3><p>Beantworten Sie zuerst „Wo beginne ich?“. Verbinden Sie die Detailartikel zu einem nachvollziehbaren Weg und bieten Sie danach Zugänge zu Sonderfällen an. Zusammenfassende Aussagen müssen aus den verlinkten Fachartikeln belegbar sein.</p><p>Nicht jede Übersicht braucht Bilder. Bildschirmabbildungen können dort stehen, wo sie einen konkreten Arbeitsschritt erklären.</p><h2 id="einheitlich-schreiben" tabindex="-1">Einheitlich schreiben <a class="header-anchor" href="#einheitlich-schreiben" aria-label="Permalink to &quot;Einheitlich schreiben&quot;">​</a></h2><ul><li>Sprechen Sie Leserinnen und Leser mit „Sie“ an. Schreiben Sie kurz und aktiv: „Wählen Sie …“, „Öffnen Sie …“.</li><li>Verwenden Sie im Fließtext „SchILD-NRW 3“, „Schülerinnen und Schüler“, „Lehrkräfte“ und „E-Mail“. Sichtbare Programmbezeichnungen bleiben unverändert, auch wenn sie davon abweichen.</li><li>Zeichnen Sie Schaltflächen und Feldnamen <strong>fett</strong> aus. Schreiben Sie Menüpfade einheitlich, zum Beispiel <strong>Verwaltung → Einstellungen → Interne Texte</strong>.</li><li>Setzen Sie Dateinamen, Verzeichnisse, Konfigurationsschlüssel und Codebezeichner in Inline-Code, etwa <code>Zeugniseinstellungen.ini</code> oder <code>ZeugnisMitRand=J</code>.</li><li>Unterscheiden Sie zwischen dem „Report“ als Vorlage und der „Ausgabe“ beziehungsweise „PDF-Ausgabe“ als erzeugtem Dokument. Nennen Sie abweichende Bezeichnungen des Programms ausdrücklich.</li><li>Beschriften Sie Links mit ihrem Zielinhalt. „Installation vorbereiten“ sagt mehr aus als „hier klicken“.</li><li>Wählen Sie einen Titel, der die Aufgabe oder den Gegenstand beschreibt. Ein Menüpunkt darf kürzer heißen. Zusätze wie „(Tutorial)“ sind dafür nicht nötig.</li></ul><h2 id="uberschriften-tabellen-und-hinweise-einsetzen" tabindex="-1">Überschriften, Tabellen und Hinweise einsetzen <a class="header-anchor" href="#uberschriften-tabellen-und-hinweise-einsetzen" aria-label="Permalink to &quot;Überschriften, Tabellen und Hinweise einsetzen&quot;">​</a></h2><p>Verwenden Sie genau einen Seitentitel mit <code>#</code>. Gliedern Sie darunter mit <code>##</code> und <code>###</code>, ohne Ebenen zu überspringen. Die rechte Übersicht „Auf dieser Seite“ entsteht aus den Überschriften; sie muss nicht von Hand gepflegt werden.</p><p>Bevorzugen Sie Markdown-Listen, Markdown-Tabellen und die vorhandenen Hinweisboxen. Tabellen eignen sich für vergleichbare, strukturierte Angaben. Verwenden Sie sie nicht als Rahmen für Fließtext oder Beispiele. Verbundene Zellen und aufwendige Zellinhalte sollten nach Möglichkeit in eine verständlichere Struktur aufgelöst werden.</p><p>Nutzen Sie Hinweise gezielt: einen Tipp für eine Arbeitserleichterung, einen Hinweis für eine Einordnung und eine Warnung für eine konkrete mögliche Fehlerfolge. Der eigentliche Arbeitsablauf muss auch außerhalb der Kästen verständlich bleiben.</p><p>HTML ist nur nötig, wenn Markdown die erforderliche Darstellung nicht abbildet oder eine bestehende Sprungmarke erhalten werden muss. Führen Sie keine eigenen Farben, Inline-Stile oder dekorativen Symbole pro Artikel ein. Die gemeinsame Gestaltung sorgt auch für die Darstellung auf kleinen Bildschirmen sowie im hellen und dunklen Modus.</p><h2 id="bilder-und-dateien-auswahlen" tabindex="-1">Bilder und Dateien auswählen <a class="header-anchor" href="#bilder-und-dateien-auswahlen" aria-label="Permalink to &quot;Bilder und Dateien auswählen&quot;">​</a></h2><p>Ein Bild soll zeigen, was für den beschriebenen Schritt wichtig ist. Beschriften Sie die entscheidenden Elemente, statt lediglich den Dateinamen zu wiederholen. Ein Alternativtext beschreibt den sichtbaren Inhalt; die Bildunterschrift erläutert dessen Bedeutung im Ablauf.</p><p>Verwenden Sie gut lesbare, passend zugeschnittene Screenshots mit möglichst einheitlichem Erscheinungsbild. Persönliche Daten müssen anonymisiert sein. Erhalten Sie vorhandene Bildunterschriften und den Zugang zum Originalbild, wenn eine Abbildung weiterhin verwendet wird.</p><p>Nutzen Sie vorhandene Abbildungen aus dem <a href="/bilder/">Bilderkatalog</a>, wenn sie zum beschriebenen Programmstand passen. Neue Bilder liegen unter <code>public/bilder/</code> im passenden Themenordner. Verwenden Sie aussagekräftige Dateinamen mit Kleinbuchstaben, Ziffern und Bindestrichen, ohne Leerzeichen oder Umlaute. Dokumente und andere Downloads liegen unter <code>public/dateien/</code>.</p><h2 id="quellen-und-geltungsbereich-erhalten" tabindex="-1">Quellen und Geltungsbereich erhalten <a class="header-anchor" href="#quellen-und-geltungsbereich-erhalten" aria-label="Permalink to &quot;Quellen und Geltungsbereich erhalten&quot;">​</a></h2><p>Bei bereits übernommenen Fachartikeln bleiben vorhandene Quellenlinks und die Angaben <code>source_pageid</code> und <code>source_revision</code> erhalten. Sie kennzeichnen die Herkunft, nicht automatisch die fachliche Aktualität.</p><p>Geben Sie einen Programmstand oder einen schulformspezifischen Geltungsbereich an, wenn die Aussage davon abhängt und dieser Zusammenhang belegt ist. Kennzeichnen Sie frühere Verfahren als solche. Behandeln Sie ungeprüfte Angaben nicht als bestätigte aktuelle Programmfunktionen.</p><p>Erhalten Sie bestehende Artikeladressen und benötigte Abschnittsanker. Prüfen Sie bei einer neuen Überschrift, ob auf die bisherige Überschrift verlinkt wird. Eine sprachliche Verbesserung soll keine vorhandenen Zugänge unbrauchbar machen.</p><h2 id="neue-artikel-auffindbar-machen" tabindex="-1">Neue Artikel auffindbar machen <a class="header-anchor" href="#neue-artikel-auffindbar-machen" aria-label="Permalink to &quot;Neue Artikel auffindbar machen&quot;">​</a></h2><p>Ordnen Sie den Artikel einem passenden Themenbereich zu und verlinken Sie ihn in dessen Übersicht oder Menü. Der Speicherort allein erzeugt keinen Menüeintrag. Wo es sinnvoll ist, kann zusätzlich die Programmreferenz auf denselben Fachartikel verweisen; dafür ist keine zweite Kopie des Artikels nötig.</p><p>Veröffentlichte Seiten erscheinen automatisch unter <a href="/hilfe/alle-artikel.html">Alle Artikel A–Z</a> und werden von der lokalen Suche erfasst. Die technischen Schritte für Dateien, Menüeinträge, lokale Vorschau und Pull Requests stehen unter <a href="https://github.com/Raffenberg/SchILD3_Doku/blob/dev/CONTRIBUTING.md" target="_blank" rel="noreferrer">An der Dokumentation mitarbeiten</a>.</p><h2 id="vor-dem-einreichen-gegenlesen" tabindex="-1">Vor dem Einreichen gegenlesen <a class="header-anchor" href="#vor-dem-einreichen-gegenlesen" aria-label="Permalink to &quot;Vor dem Einreichen gegenlesen&quot;">​</a></h2><p>Lesen Sie den Artikel in der Vorschau: Ist der Ablauf verständlich? Stimmen Begriffe, Bilder und Verweise? Sind fachliche Änderungen erkennbar und begründet? Bleiben Tabellen und Code auch auf einem kleinen Bildschirm nutzbar?</p><p>Beschreiben Sie im Pull Request kurz, was geändert wurde und worauf die fachlichen Angaben beruhen. Ein dauernder Vergleich mit früheren Artikelprüfsummen ist dafür nicht erforderlich.</p>',41)])])}const g=n(a,[["render",l]]);export{o as __pageData,g as default};
